function displayCatInfos() {
  let infoContainer = document.querySelector(".category-infos");
  let showMore = document.querySelector(".show-more-btn");
  let isExpanded = false;

  showMore.addEventListener("click", function () {
    const windowWidth = window.innerWidth;

    if (isExpanded) {
      // Rétracter
      infoContainer.style.height = windowWidth <= 540 ? "225px" : "160px";
      showMore.textContent = "+";
    } else {
      // Étendre
      infoContainer.style.height = windowWidth <= 540 ? "1020px" : "850px";
      showMore.textContent = "-";
    }
    isExpanded = !isExpanded;
  });
}

function fixedImgBanner() {
  let imgBanner = document.querySelector(".category-banner-image");
  let infosContainer = document.querySelector(".cat-infos_container");
  const offset = 100;

  document.addEventListener("scroll", function () {
    let scrollPosition = window.scrollY || document.documentElement.scrollTop;
    let containerBottom =
      infosContainer.offsetTop + infosContainer.offsetHeight + offset;

    if (scrollPosition >= containerBottom) {
      imgBanner.classList.add("fixed");
    } else {
      imgBanner.classList.remove("fixed");
    }
  });
}

fixedImgBanner();
displayCatInfos();
